      : item.type === "meaningfulMomentReached" && (!item.momentId || item.momentId === fresh.highSchoolMatch.currentMomentId))
  );
  if ((readyHighSchoolMoment || readyHighSchoolAgency) && !hasReadyHighSchoolMomentEvent) {
